(function(){'use strict';
const AVATAR_SERVICE='Trái Vĩnh Viễn BF',AVATAR_IMG='data:image/png;base64,';
let n=0;
function addAvatar(){if(typeof serviceAvatars==='undefined'||!serviceAvatars)return false;serviceAvatars[AVATAR_SERVICE]=AVATAR_IMG;if(typeof renderServices==='function')renderServices();return true}
function retry(){if(!addAvatar()&&n++<200)setTimeout(retry,100)}
function boot(){retry()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.addEventListener('load',()=>{setTimeout(boot,300);setTimeout(boot,1000)});
})();
